// divide returns the quotient AND an error describing any failure.
func divide(a, b int) (int, error) {
	if b == 0 {
		return 0, errors.New("divide by zero") // zero value + error
	}
	return a / b, nil // nil error means success
}

func main() {
	q, err := divide(10, 2)
	if err != nil {
		fmt.Println("error:", err)
	} else {
		fmt.Println("10 / 2 =", q)
	}

	_, err = divide(10, 0)
	fmt.Println("second call error:", err)
}

