package solution

import "errors"

func Solve(nums []int) (min, max int, err error) {
	if len(nums) == 0 {
		err = errors.New("empty slice") // min,max stay at zero values
		return                          // naked return is fine in a short func
	}
	min, max = nums[0], nums[0] // seed with the first element
	for _, n := range nums[1:] {
		if n < min {
			min = n
		}
		if n > max {
			max = n
		}
	}
	return min, max, nil
}

