package solution

import "testing"

func TestSolve(t *testing.T) {
	cases := []struct {
		in            []int
		wMin, wMax    int
		wErr          bool
	}{
		{[]int{3, 1, 4, 1, 5}, 1, 5, false},
		{[]int{42}, 42, 42, false},
		{[]int{-2, -9, -1}, -9, -1, false},
		{[]int{}, 0, 0, true},
	}
	for _, c := range cases {
		min, max, err := Solve(c.in)
		if (err != nil) != c.wErr {
			t.Errorf("Solve(%v) err=%v wantErr=%v", c.in, err, c.wErr)
			continue
		}
		if err == nil && (min != c.wMin || max != c.wMax) {
			t.Errorf("Solve(%v)=(%d,%d) want (%d,%d)", c.in, min, max, c.wMin, c.wMax)
		}
	}
}

