func Map(xs []int, f func(int) int) []int {
	out := make([]int, len(xs)) // pre-sized result
	for i, x := range xs {
		out[i] = f(x) // f is a first-class function value
	}
	return out
}

func MakeAdder(base int) func(int) int {
	// The returned literal closes over base, capturing it by reference.
	return func(x int) int {
		return base + x
	}
}

